import{_ as e,c as r,o as i,af as t}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第十四卦 大有 火天大有 離上乾下","description":"周易 - 第十四卦 大有 火天大有 離上乾下","frontmatter":{"title":"第十四卦 大有 火天大有 離上乾下","description":"周易 - 第十四卦 大有 火天大有 離上乾下"},"headers":[],"relativePath":"classics/zhouyi/015.md","filePath":"classics/zhouyi/015.md"}'),h={name:"classics/zhouyi/015.md"};function l(s,a,n,o,c,d){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="大有" tabindex="-1">大有 <a class="header-anchor" href="#大有" aria-label="Permalink to “大有”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>元亨。 彖曰：大有，柔得尊位，大中而上下應之，曰大有。其德剛健而文明，應乎天而時行，是以元亨。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>火在天上，大有；君子以竭惡揚善，順天休命。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>無交害，匪咎，艱則無 咎。象曰：大有初九，無交害也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>大車以載，有攸往，無咎。象曰：大車以載，積中不敗也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>公用亨於天子，小人弗克。象曰：公用亨於天子，小人害也。九四：匪其彭，無咎。象曰：匪其彭，無咎；明辨晰也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>厥孚交如，威如；吉。象曰：厥孚交如，信以發志也。威如之吉，易而無備也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>自天佑之，吉無不利。象曰：大有上吉，自天佑也。</p>',15)])])}const f=e(h,[["render",l]]);export{_ as __pageData,f as default};
